package com.integrydt.backend.controller;

import com.integrydt.backend.service.DeviceTokenService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.FileSystemResource;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
import java.io.File;import java.nio.file.*;import java.util.*;

@RestController @RequestMapping("/api/v1/agent")
public class AgentController {
 private final JdbcTemplate db;private final DeviceTokenService tokens;private final String enrollmentKey;private final Path gadgetRoot;
 public AgentController(JdbcTemplate db,DeviceTokenService tokens,@Value("${integry.client.enrollment-key}") String enrollmentKey,@Value("${integry.gadget-storage}") String gadgetRoot){this.db=db;this.tokens=tokens;this.enrollmentKey=enrollmentKey;this.gadgetRoot=Paths.get(gadgetRoot).toAbsolutePath().normalize();}
 public record EnrollRequest(String companySlug,String name,String machineKey,String os,String architecture,String agentVersion){}
 @PostMapping("/enroll") public ResponseEntity<?> enroll(@RequestBody EnrollRequest r,@RequestHeader(value="X-Enrollment-Key",required=false) String key){if(enrollmentKey==null||enrollmentKey.isBlank()||!enrollmentKey.equals(key))return ResponseEntity.status(401).build();var cs=db.queryForList("SELECT CAST(id AS CHAR) id FROM companies WHERE slug=? AND status='active'",r.companySlug());if(cs.isEmpty())return ResponseEntity.badRequest().body(Map.of("error","company_not_found"));String company=(String)cs.get(0).get("id");var ds=db.queryForList("SELECT CAST(id AS CHAR) id FROM devices WHERE company_id=? AND machine_key=?",company,r.machineKey());String device;if(ds.isEmpty()){device=UUID.randomUUID().toString();db.update("INSERT INTO devices(id,company_id,name,machine_key,os,architecture,agent_version,status) VALUES(?,?,?,?,?,?,?,'offline')",device,company,r.name(),r.machineKey(),r.os(),r.architecture(),r.agentVersion());}else{device=(String)ds.get(0).get("id");db.update("UPDATE devices SET name=?,os=?,architecture=?,agent_version=? WHERE id=?",r.name(),r.os(),r.architecture(),r.agentVersion(),device);db.update("UPDATE device_credentials SET revoked_at=CURRENT_TIMESTAMP(6) WHERE device_id=? AND revoked_at IS NULL",device);}String token=tokens.createToken();db.update("INSERT INTO device_credentials(id,device_id,credential_hash) VALUES(?,?,?)",UUID.randomUUID().toString(),device,tokens.hash(token));return ResponseEntity.ok(Map.of("deviceId",device,"deviceToken",token));}
 @GetMapping("/gadget-package/{versionId}") public ResponseEntity<?> packageFile(@PathVariable String versionId,@RequestParam String deviceId,HttpServletRequest req){String a=req.getHeader("Authorization");if(a==null||!a.regionMatches(true,0,"Bearer ",0,7)||!tokens.validate(deviceId,a.substring(7)))return ResponseEntity.status(401).build();var rows=db.queryForList("SELECT gv.storage_key storageKey,gv.status FROM gadget_versions gv JOIN jobs j ON j.gadget_version_id=gv.id WHERE gv.id=? AND j.device_id=? AND j.status IN ('queued','dispatched','downloading_gadget','running') LIMIT 1",versionId,deviceId);if(rows.isEmpty()||!"published".equals(rows.get(0).get("status")))return ResponseEntity.notFound().build();String key=(String)rows.get(0).get("storageKey");Path p=gadgetRoot.resolve(key.replace('/',File.separatorChar)).resolve("package.zip").normalize();if(!p.startsWith(gadgetRoot)||!Files.isRegularFile(p))return ResponseEntity.notFound().build();File f=p.toFile();return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/zip")).contentLength(f.length()).body(new FileSystemResource(f));}
}
